#include "judge_json.h"
#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int append_utf8(char *out,size_t cap,size_t *used,unsigned cp){unsigned char b[4];size_t n;if(cp<0x80){b[0]=(unsigned char)cp;n=1;}else if(cp<0x800){b[0]=(unsigned char)(0xc0|(cp>>6));b[1]=(unsigned char)(0x80|(cp&63));n=2;}else if(cp<0x10000){b[0]=(unsigned char)(0xe0|(cp>>12));b[1]=(unsigned char)(0x80|((cp>>6)&63));b[2]=(unsigned char)(0x80|(cp&63));n=3;}else if(cp<=0x10ffff){b[0]=(unsigned char)(0xf0|(cp>>18));b[1]=(unsigned char)(0x80|((cp>>12)&63));b[2]=(unsigned char)(0x80|((cp>>6)&63));b[3]=(unsigned char)(0x80|(cp&63));n=4;}else return 0;if(n>=cap||*used>=cap-n)return 0;memcpy(out+*used,b,n);*used+=n;return 1;}
static int hex4(const unsigned char *p,unsigned *v){unsigned x=0;for(int i=0;i<4;i++){unsigned char c=p[i];unsigned d;if(c>='0'&&c<='9')d=c-'0';else if(c>='a'&&c<='f')d=c-'a'+10;else if(c>='A'&&c<='F')d=c-'A'+10;else return 0;x=(x<<4)|d;}*v=x;return 1;}
static int json_string(const unsigned char *p,const unsigned char *end,char *out,size_t cap,const unsigned char **after){size_t used=0;if(p>=end||*p!='"')return 0;p++;while(p<end&&*p!='"'){unsigned char byte=*p++;if(byte>=0x80){if(used+1>=cap)return 0;out[used++]=(char)byte;continue;}unsigned cp=byte;if(cp<0x20)return 0;if(cp=='\\'){if(p>=end)return 0;unsigned char e=*p++;switch(e){case '"':cp='"';break;case '\\':cp='\\';break;case '/':cp='/';break;case 'b':cp='\b';break;case 'f':cp='\f';break;case 'n':cp='\n';break;case 'r':cp='\r';break;case 't':cp='\t';break;case 'u':{unsigned hi;if((size_t)(end-p)<4||!hex4(p,&hi))return 0;p+=4;if(hi>=0xd800&&hi<=0xdbff){if((size_t)(end-p)<6||p[0]!='\\'||p[1]!='u')return 0;unsigned lo;if(!hex4(p+2,&lo)||lo<0xdc00||lo>0xdfff)return 0;p+=6;cp=0x10000+((hi-0xd800)<<10)+(lo-0xdc00);}else if(hi>=0xdc00&&hi<=0xdfff)return 0;else cp=hi;break;}default:return 0;}}if(cp<0x80){if(used+1>=cap)return 0;out[used++]=(char)cp;}else if(!append_utf8(out,cap,&used,cp))return 0;}if(p>=end||*p!='"')return 0;out[used]=0;if(after)*after=p+1;return 1;}
static const unsigned char *find_key(const unsigned char *p,const unsigned char *end,const char *key){size_t n=strlen(key);for(;p+n+2<=end;p++)if(*p=='"'&&!memcmp(p+1,key,n)&&p[n+1]=='"'){const unsigned char *q=p+n+2;while(q<end&&isspace(*q))q++;if(q<end&&*q==':'){q++;while(q<end&&isspace(*q))q++;return q;}}return NULL;}
int ama10_json_string_field(const unsigned char *json,size_t n,const char *field,char *out,size_t cap){if(!json||!field||!out||!cap)return 0;const unsigned char *end=json+n,*p=find_key(json,end,field);return p&&json_string(p,end,out,cap,NULL);}
static int field_string(const char *json,const char *key,char *out,size_t cap){const unsigned char *p=(const unsigned char*)json,*end=p+strlen(json);p=find_key(p,end,key);return p&&json_string(p,end,out,cap,NULL);}
static int field_int(const char *json,const char *key,int *value){const unsigned char *p=(const unsigned char*)json,*end=p+strlen(json);p=find_key(p,end,key);if(!p)return 0;char *q=NULL;long x=strtol((const char*)p,&q,10);if(q==(char*)p||x<1||x>5)return 0;while(q<(const char*)end&&isspace((unsigned char)*q))q++;if(q<(const char*)end&&*q!=','&&*q!='}')return 0;*value=(int)x;return 1;}
int ama10_parse_preference_judgment(const char *s,char *choice,size_t cap,int *a,int *b){if(!s||!choice||!cap||!a||!b)return 0;char c[16];if(!field_string(s,"choice",c,sizeof(c))||!field_int(s,"score_a",a)||!field_int(s,"score_b",b))return 0;if(strcmp(c,"A")&&strcmp(c,"B")&&strcmp(c,"TIE"))return 0;if(strlen(c)>=cap)return 0;strcpy(choice,c);return 1;}
